                if i len(prev_costs):
                    return float('inf')
            for i in sorted_prev:
                if i not in bad_set[j]:
                    results[j] = prev_costs[i] + curr_costs[j]
                    break
        return results

    cat1_2 = compute_min(a, b, n1, n2, bad_1_2)
    if min(cat1_2) == float('inf'):
        return "-1"

    cat2_3 = compute_min(cat1_2, c, n2, n3, bad_2_3)
