import sys

def is_gp(seq):
    """
    Check if a sequence is a geometric progression.
    For three consecutive terms a, b, c to be in GP, we need b² = a × c.
    """
    n = len(seq)
    if n <= 2:
        return True

    # If all zeros, it's a GP (ratio can be anything, but all terms are 0)
    if all(x == 0 for x in seq):
        return True

    # For each triplet (a, b, c), check if b² = a * c
    for i in range(n - 2):
        a, b, c = seq[i], seq[i+1], seq[i+2]
        if b * b != a * c:
            return False

    return True

