    # Parse input
    parts = input_str.strip().split()
    if len(parts) < 1:
        return "2\n"
    n = int(parts[0])
    if len(parts) < n + 1:
        # Handle malformed input
        seq = [int(x) for x in parts[1:]]
    else:
        seq = [int(x) for x in parts[1:n+1]]

    # Check if already a GP
    if is_gp(seq):
        return "0\n"

    # Try removing each element one by one
    for i in range(len(seq)):
        new_seq = seq[:i] + seq[i+1:]
        if is_gp(new_seq):
