    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        # First n lines are color grid
        c_grid = []
        for _ in range(n):
            c_grid.append(lines[idx])
            idx += 1

        # Next n lines are direction grid
        s_grid = []
        for _ in range(n):
            s_grid.append(lines[idx])
            idx += 1

        # Build adjacency list - each cell points to exactly one cell
        adj = [[0] * m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                d = s_grid[i][j]
                if d == 'U':
                    adj[i][j] = (i - 1, j)
                elif d == 'D':
                    adj[i][j] = (i + 1, j)
                elif d == 'L':
                    adj[i][j] = (i, j - 1)
                elif d == 'R':
                    adj[i][j] = (i, j + 1)

        # Find all cycles and count their properties
        states = [[0] * m for _ in range(n)]  # 0=unvisited, 1=visiting, 2=done

        cycle_count = 0
        black_in_cycles = 0

        for i in range(n):
            for j in range(m):
                if not states[i][j]:
                    # Follow the path from this starting cell
