                        # Found a cycle - the cycle starts at the first occurrence of curr in path
                        cycle_idx = path.index(curr)
                        cycle = path[cycle_idx:]

                        # Count cycle and its black cells
                        cycle_count += len(cycle)
                        for cell in cycle:
                            if c_grid[cell[0]][cell[1]] == '1':
                                black_in_cycles += 1

                        # Mark cycle nodes as done to avoid recounting
