            before_col = counts[i + 1][j][:]
            new_row = before_row + before_col - counts[i][j][:]
            new_row[c] += 1
            counts[i + 1][j + 1] = new_row

    def get_row_counts(r1, c1, r2, c2):
        return [counts[r][c] - counts[r1][c] for r in [r1, r2 + 1] 
                for c in [c1, c2 + 1] if r > r1 or c > c1 else []]

    def get_col_counts(r1, c1, r2, c2):
