def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        parts = list(map(int, lines[i].split()))
        u, v = parts[0], parts[1]
        adj[u].append(v)
        adj[v].append(u)

    # Strategy: Try to find Johnny's path first (length >= n/k)
    # If not possible or path finding is slow, try Solving's cycles

    target_len = n // k

    # DFS to find a simple path
    found_path = None

    def dfs_path(start, path, visited):
        nonlocal found_path
        if len(path) >= target_len + 1:
            found_path = list(path)
            return True

        for neighbor in adj[start]:
            if neighbor not in visited:
                visited.add(neighbor)
                path.append(neighbor)
                if dfs_path(neighbor, path, visited):
                    return True
                path.pop()
                visited.remove(neighbor)
        return False

    # Try starting from each vertex
    for start in range(1, n + 1):
        if found_path:
            break
        found_path = None
        visited = {start}
        dfs_path(start, [start], visited)

    # If we found a valid path
    if found_path and len(found_path) >= target_len + 1:
        output_lines = ["PATH", str(len(found_path)), " ".join(map(str, found_path))]
        print('\n'.join(output_lines))
        return

    # Otherwise, try to find k cycles for Solving
    cycles = []
    visited_global = [False] * (n + 1)

    def find_cycles_from(start, min_cycle_len):
        if start >= n or cycles >= k:
            return

        stack = [(start, [start])]
        while stack and len(cycles) < k:
            vertex, path = stack.pop()

            for neighbor in adj[vertex]:
                if neighbor == path[0] and len(path) >= min_cycle_len:
                    # Found a cycle
                    cycle = path + [path[0]]
                    cycle_len = len(cycle)

                    if cycle_len >= 3 and cycle_len % 3 != 0:
                        # Check if vertex can be representative (not in other cycles' first pos)
                        if start not in [c[0] for c in cycles]:
                            cycles.append((cycle, start))
                            visited_global[start] = True
                    else:
                        # Cycle length divisible by 3 or too short, skip
                        pass
                elif neighbor not in {p for p in path}:
                    stack.append((neighbor, path + [neighbor]))

    # Try to find cycles from each vertex
    for start in range(1, n + 1):
        if len(cycles) >= k:
            break
        find_cycles_from(start, 3)
        if len(cycles) >= k:
            break

    # Helper to format cycle output
    def format_cycle(cycle_tuple):
        cycle, rep = cycle_tuple
        cycle_str = []
        for v in cycle:
            cycle_str.append(str(v))
        return f"{len(cycle)}\n{' '.join(cycle_str)}"

    if len(cycles) >= k:
        output = ["CYCLES", ]
        for i in range(min(k, len(cycles))):
            output.append(format_cycle(cycles[i]))
        print('\n'.join(output))
    else:
        # Fallback: try to create more cycles with a different approach
        # Each cycle must have a unique representative

        cycles = []
        used_reps = set()

        def build_cycle(start):
            nonlocal cycles
            path = [start]
            current = start

            for _ in range(len(adj[start]) + 2):
                for neighbor in adj[current]:
                    if neighbor in path and len(path) >= 3:
                        cycle = path + [neighbor]
                        if len(cycle) >= 3 and len(cycle) % 3 != 0:
                            cycles.append((cycle, start))
                            used_reps.add(start)
                            return path
                        else:
                            # Shorter cycle divisible by 3, backtrack further
                            break
                    if neighbor not in path:
                        path.append(neighbor)
                        current = neighbor
                        break
                else:
                    continue
                break
            return path

        for i in range(n):
            start = (i % n) + 1
            if start not in used_reps and start in adj:
                path = build_cycle(start)
                if path:
                    start_cycle = path[0]
                    for v_idx, v in enumerate(path):
                        if v in path and len(path) >= 3:
                            cycle = path + [v]
                            if len(cycle) >= 3 and len(cycle) % 3 != 0:
                                if start_cycle not in used_reps:
                                    cycles.append((cycle, start_cycle))
                                    used_reps.add(start_cycle)
                                break

        if len(cycles) >= k:
            output = ["CYCLES", ]
            for i in range(min(k, len(cycles))):
                cycle, rep = cycles[i]
                cycle_str = " ".join(map(str, cycle))
                output.append(f"{len(cycle)}")
                output.append(cycle_str)
            print('\n'.join(output))
        else:
            print("-1")

