import math
from collections import deque

def solution(s):
    """
    Given a connected graph, find either:
    - An independent set of size >= ceil(sqrt(n)), OR
    - A simple cycle of length >= ceil(sqrt(n))
    """
    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    min_len = int(math.ceil(math.sqrt(n)))

    # DFS to find a long cycle
    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    depths = [-1] * (n + 1)  # -1 to ensure valid comparison
    timer = [0]

    def dfs(u, p=0):
        visited[u] = True
        parent[u] = p
        depths[u] = timer[0]
        timer[0] += 1

        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                if depths[v] < depths[u]:
                    # Back edge found - potential cycle
                    cycle_len = depths[u] - depths[v] + 1
                    if cycle_len >= min_len:
                        path = []
                        curr = u
                        while True:
                            path.append(curr)
                            if curr == v:
                                break
                            curr = parent[curr]
                        path.reverse()
                        return path
            else:
                res = dfs(v, u)
                if res:
                    return res
        return None

    # Try to find cycle from each unvisited component
    visited = [False] * (n + 1)
    for start in range(1, n + 1):
        if not visited[start]:
            result = dfs(start)
            if result:
                return f"2\n{len(result)}\n{' '.join(map(str, result))}"

    # Find independent set via BFS coloring
    color = [-1] * (n + 1)

    for start_node in range(1, n + 1):
        if color[start_node] == -1:
            # BFS to color this component
            queue = deque([start_node])
            color[start_node] = 0
            count = [0, 0]
            count[0] = 1

            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        count[color[v]] += 1
                        queue.append(v)

            # Take the larger color class for this component
            larger = 0 if count[0] >= count[1] else 1
            for i in range(1, n + 1):
                if color[i] == -1 and reachable_from(start_node, adj, color[i], 100, i == 1 or color[start_node] == 0):
                    color[i] = -1
                    color[i] = larger

    # Collect independent set nodes
    set_size_0 = 0
    set_size_1 = 0
    for i in range(1, n + 1):
        if i in color:
            if color[i] == 0:
                set_size_0 += 1
            elif color[i] == 1:
                set_size_1 += 1

    chosen = 0 if set_size_0 >= set_size_1 else 1
    result_set = [i for i in range(1, n + 1) if color[i] == chosen]

    return f"1\n{' '.join(map(str, result_set))}"


