def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    trees = []
    for i in range(1, n + 1):
        a, h, l, r = map(int, lines[i].split())
        trees.append((a, h, l, r))

    mushrooms = []
    for i in range(n + 1, n + m + 1):
        b, z = map(int, lines[i].split())
        mushrooms.append((b, z))

    total_expected = 0.0

    for b, z in mushrooms:
        survival_prob = 1.0

        for a, h, l, r in trees:
            left_min = a - h
            left_max = a
            right_min = a
            right_max = a + h

            if left_min <= b < left_max:
                # In left interval: destroyed if falls left with prob l/100
                # Survives if falls right (r/100) or stands ((100-l-r)/100)
                p_survives = (r + 100 - l - r) / 100.0
                survival_prob *= p_survives
            elif right_min < b <= right_max:
                # In right interval: destroyed if falls right with prob r/100
                # Survives if falls left (l/100) or stands ((100-l-r)/100)
                p_survives = (l + 100 - l - r) / 100.0
                survival_prob *= p_survives
            else:
                # Not in any destruction interval
                p_survives = 1.0
                survival_prob *= p_survives

        total_expected += survival_prob * z

    return f"{total_expected:.10f}\n"


