class Dinic:
    INF = 100000

    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.inf_edges = set()
        self.source = None
        self.sink = None

    def add_edge(self, u, v, cap):
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])
        if cap == self.INF:
            self.inf_edges.add((u, v))

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, rev in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, pushed, ptr):
        if pushed == 0 or u == t:
            return pushed
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev = self.graph[u][i]
            if self.level[u] + 1 != self.level[v] or cap == 0:
                continue
            tr = self.dfs(v, t, min(pushed, cap), ptr)
            if tr == 0:
                continue
            self.graph[u][i][1] -= tr
            self.graph[v][rev][1] += tr
            return tr
        return 0

    def max_flow(self, s, t):
        self.source = s
        self.sink = t
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, self.INF, ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow

