        def sort_stable(table: List[List[int]], col: int) -> List[List[int]]:
            n_local = len(table)
            if n_local == 1:
                return table

            # Group by column value
            from collections import defaultdict
            groups = defaultdict(list)
            for i in range(n_local):
                groups[table[i][col]].append(i)

            # Create result preserving relative order within same column values
            result = [None] * n_local
            idx = 0
            for col_val in sorted(groups.keys()):
