import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    x_values = list(map(int, lines[1].split()))
    special_y = int(lines[2])

    # Cities on x-axis: x_values[0] to x_values[n-1]
    # Special city: x_values[n], special_y
    cities_x = x_values[:n]
    special_x = x_values[n]

    min_x = min(cities_x)
    max_x = max(cities_x)

    # Starting position (1-indexed k)
    if k <= n:
        start_x = cities_x[k-1]
        start_on_xaxis = True
    else:
        start_x = special_x
        start_on_xaxis = False

    def dist(x1, y1, x2, y2):
        return math.sqrt((x1 - x2)**2 + (y1 - y2)**2)

    # Pattern 1: Start -> special -> min_x -> max_x (left-to-right)
    if start_on_xaxis:
        cost1 = dist(start_x, 0, special_x, special_y) + dist(special_x, special_y, min_x, 0) + (max_x - min_x)
    else:
        cost1 = dist(special_x, special_y, min_x, 0) + (max_x - min_x)

    # Pattern 2: Start -> min_x -> special -> max_x (special at left)
    if start_on_xaxis:
        cost2 = abs(start_x - min_x) + dist(min_x, 0, special_x, special_y) + (max_x - min_x)
    else:
        cost2 = dist(special_x, special_y, min_x, 0) + dist(min_x, 0, max_x, 0)

    # Pattern 3: Start -> min_x -> max_x -> special (special at right)
    if start_on_xaxis:
        cost3 = abs(start_x - min_x) + (max_x - min_x) + dist(max_x, 0, special_x, special_y)
    else:
        cost3 = (max_x - min_x) + dist(max_x, 0, special_x, special_y)

    # Pattern 4: Start -> special -> max_x -> min_x (right-to-left)
    if start_on_xaxis:
        cost4 = dist(start_x, 0, special_x, special_y) + dist(special_x, special_y, max_x, 0) + (max_x - min_x)
    else:
        cost4 = dist(special_x, special_y, max_x, 0) + (max_x - min_x)

    # Pattern 5: Start -> max_x -> special -> min_x (special at right)
    if start_on_xaxis:
        cost5 = abs(start_x - max_x) + dist(max_x, 0, special_x, special_y) + (max_x - min_x)
    else:
        cost5 = dist(special_x, special_y, max_x, 0) + dist(max_x, 0, min_x, 0)

    # Pattern 6: Start -> max_x -> min_x -> special (special at left)
    if start_on_xaxis:
        cost6 = abs(start_x - max_x) + (max_x - min_x) + dist(min_x, 0, special_x, special_y)
    else:
        cost6 = (max_x - min_x) + dist(min_x, 0, special_x, special_y)

    return f"{min(float(cost1), float(cost2), float(cost3), float(cost4), float(cost5), float(cost6)):.20g}"

