        if val not in first:
            first[val] = i
        last[val] = i

    distinct = sorted(first.keys())
    distinct_len = len(distinct)

    if distinct_len <= 1:
        return distinct_len

    # Track longest chain where values are consecutive in sorted_distinct
    # and all-occurrences of value i come before all-occurrences of value i+1
    max_chain = 1
    current_chain = 1

    for i in range(distinct_len - 1):
