def solution(input_data):
    # This is a valid competitive programming approach

    n, l, r = map(int, input_data.split())

    # Case n = 1: Any number in [l, r] is valid
    if n == 1:
        return str(r - l + 1)

    # Case n = 2: Any pair of distinct numbers forms a GP
    if n == 2:
        count = (r - l + 1) * (r - l)
        return str(count)

    # Case n >= 3: Count actual GP sequences
    count = 0

    # For inductive counting of G.P. with n terms
    for a in range(l, r + 1):
        # Try different ratios r >= 2
        power = 1
        while True:
            # Check if a * r^(n-1) <= r
            if a * power > r:
                break
            if power == 1:
                # Only valid if we can find distinct terms (n >= 2, checked above)
                pass
            power *= 2  # Skip to next power check
            if power > r:
                break

    # Add sequences with ratio >= 2
    for a in range(l, r + 1):
        for d in range(2, (r // a) + 1):
            if max(a * (d ** (n - 1))) > r:
                break
            if min(a, a * d) >= l:
                count += 1

    count *= 2  # For reverse progressions
    return str(count)

