def solution(input_text):
    # Parse input
    lines = input_text.strip().split('\n')
    if not lines:
        return "-1\n"

    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i <= len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    # Generate lucky numbers up to n
    lucky_numbers = generate_lucky_numbers(n)

    # Find connected components and their sizes
    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            stack = [i]
            while stack:
                node = stack.pop()
                if visited[node]:
                    continue
                visited[node] = True
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
            components.append(size)

    # If no components, impossible
    if not components:
        return "-1\n"

    # Check if any single component already has a lucky size
    for size in components:
        for target in lucky_numbers:
            if size == target:
                return "0\n"

    # DP: dp[s] = minimum number of components needed to achieve sum s
    dp = {0: 0}

    for size in components:
        new_dp = dict(dp)
        for s, count in dp.items():
            if s + size <= n:
                new_count = count + 1
                if new_count < new_dp.get(s + size, float('inf')):
                    new_dp[s + size] = new_count
        dp = new_dp

    # Find minimum roads needed (k-1 where k is number of components merged)
    ans = float('inf')
    for target in lucky_numbers:
        if target in dp:
            ans = min(ans, dp[target])

    if ans == float('inf'):
        return "-1\n"

    return f"{ans - 1}\n"

