def lagrange_interpolate(x_coords, y_coords, n):
    from math import factorial
    MOD = 998244353

    def inv(a):
        return pow(a, MOD - 2, MOD)

    def poly_eval(coeffs, x):
        result = 0
        for i, c in enumerate(coeffs):
            result = (result + c * pow(x, i, MOD)) % MOD
        return result

    def binom(n, k):
        return factorial(n) * inv(factorial(k)) * inv(factorial(n - k))

    coeffs = [0] * len(x_coords)
    for i, xi in enumerate(x_coords):
        factor = y_coords[i]
        for j in range(i + 1):
