from functools import lru_cache

def solution(s):
    n, k, m = map(int, s.strip().split())
    mod = 10**9 + 7

    @lru_cache(maxsize=None)
    def dp(step, last, visited):
        """
        step: number of planets visited so far
        last: index of the last visited planet
        visited: frozenset of visited planets
        """
        if step == k:
            return 1

        count = 0
        # Can move to any planet in [1, min(n, last + m)] that hasn't been visited
        limit = min(n, last + m)
        for y in range(1, limit + 1):
            if y not in visited:
                new_visited = visited | {y}
                count = (count + dp(step + 1, y, new_visited)) % mod

        return count

    # Sum over all possible starting planets
    ans = 0
    for start in range(1, n + 1):
        ans = (ans + dp(1, start, frozenset({start}))) % mod

    return str(ans)
